CREATE TYPE "CertificateType" AS ENUM ('BONAFIDE','CHARACTER','STUDY','FEE','TRANSFER','MIGRATION','COURSE_COMPLETION','CUSTOM');CREATE TYPE "CertificateStatus" AS ENUM ('DRAFT','ISSUED','ARCHIVED','REVOKED');
CREATE TABLE "Certificate" ("id" TEXT NOT NULL,"certificateNumber" TEXT NOT NULL,"studentId" TEXT NOT NULL,"branchId" TEXT NOT NULL,"courseId" TEXT,"batchId" TEXT,"type" "CertificateType" NOT NULL,"customType" TEXT,"issueDate" DATE,"purpose" TEXT NOT NULL,"status" "CertificateStatus" NOT NULL DEFAULT 'DRAFT',"remarks" TEXT,"templateKey" TEXT NOT NULL DEFAULT 'standard',"verificationToken" TEXT NOT NULL,"digitalSignature" TEXT,"issuedById" TEXT,"issuedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Certificate_pkey" PRIMARY KEY ("id"));ALTER TABLE "Certificate" ADD CONSTRAINT "Certificate_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "StudentProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Certificate" ADD CONSTRAINT "Certificate_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Certificate" ADD CONSTRAINT "Certificate_courseId_fkey" FOREIGN KEY ("courseId") REFERENCES "Course"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Certificate" ADD CONSTRAINT "Certificate_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "Batch"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Certificate" ADD CONSTRAINT "Certificate_issuedById_fkey" FOREIGN KEY ("issuedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE UNIQUE INDEX "Certificate_certificateNumber_key" ON "Certificate"("certificateNumber");CREATE UNIQUE INDEX "Certificate_verificationToken_key" ON "Certificate"("verificationToken");CREATE INDEX "Certificate_studentId_idx" ON "Certificate"("studentId");CREATE INDEX "Certificate_branchId_idx" ON "Certificate"("branchId");CREATE INDEX "Certificate_courseId_idx" ON "Certificate"("courseId");CREATE INDEX "Certificate_batchId_idx" ON "Certificate"("batchId");CREATE INDEX "Certificate_status_idx" ON "Certificate"("status");CREATE INDEX "Certificate_issueDate_idx" ON "Certificate"("issueDate");
